  redeemSettleDays: number
  /** 首次申购最低金额，单位元 */
  minFirstPurchase: Nullable<Money>
  /** 追加申购最低金额 */
  minAdditionalPurchase: Nullable<Money>
  /** 最低赎回份额 */
  minRedeemShares: Nullable<import('./common').Shares>
