/**
 * 份额拆分/折算记录。
 * 拆分后份额增加、净值等比下降，总资产不变。
 */
export interface SplitRecord {
  code: FundCode
  /** 拆分实施日 */
  date: TradingDate
  /** 拆分比例。2 表示 1 份拆为 2 份，净值减半 */
  ratio: number
}

// ============================================================
// 聚合视图
// ============================================================

/**
 * 一只基金的全量数据聚合。
 *
 * 【使用建议】不要在组件里直接持有整个对象。
 * navSeries 可能有数千条记录，全局仓库应按 code 分片存储，
