}

/**
 * 全局基金数据仓库。所有自选组共享同一份实例。
 */
export interface FundRepository {
  /** 以基金代码为键的数据表 */
  funds: Record<FundCode, FundData>
  /** 已收录的基金代码列表 */
  codes: FundCode[]
}
