  requestAmount: Nullable<Money>
  /**
   * 赎回份额。仅 side='redeem' 时有值。
   */
  requestShares: Nullable<Shares>
  /**
   * 指定赎回的持仓批次。为空则按组配置的 lotStrategy（默认 FIFO）自动选择。
   * 允许策略精确指定要卖哪一批，这对分批建仓的马丁策略很关键。
