   * 实际成交金额（不含费用的净额）。
   * 申购：requestAmount - fee
   * 赎回：requestShares * confirmNav
   */
  confirmedAmount: Nullable<Money>

  // ---------- 费用 ----------
  /** 实际收取的费用，单位元 */
  fee: Nullable<Money>
  /** 实际适用的费率，用于展示与审计 */
  feeRate: Nullable<Rate>

