  id: LotId
  fundCode: FundCode
  /** 产生该批次的申购订单 */
  sourceOrderId: OrderId
  /**
   * 建仓日期，即份额确认日。
   * 持有天数从这一天起算（自然日，非交易日）。
   */
  openDate: TradingDate
  /** 建仓时的单位净值，即该批次的成本净值 */
  costNav: NetValue
