 * 现金账户快照。
 *
 * 【三态现金】必须区分，否则会出现「明明显示有钱却买不了」的 bug：
 * - available：可立即用于申购
 * - frozen：已下申购单但未确认，已扣但份额未到
 * - inTransit：赎回已确认但资金未到账
 */
export interface CashAccount {
  /** 可用现金 */
  available: Money
  /** 申购冻结中的现金 */
  frozen: Money
  /** 赎回在途资金 */
  inTransit: Money
  /** 现金总额 = available + frozen + inTransit */
  total: Money
}

/** 资金流水类型 */
export type CashFlowType =
  | 'deposit' // 外部注资
  | 'withdraw' // 外部提取
  | 'purchaseFreeze' // 申购冻结
  | 'purchaseSettle' // 申购确认扣款
  | 'purchaseRefund' // 申购失败退款
  | 'redeemArrive' // 赎回到账
  | 'dividendCash' // 现金分红入账

/**
 * 资金流水记录。
 * 【为什么需要】现金余额也应可推导可审计。
 * 外部注资/提取是无法由订单推导的独立事实，必须单独记录。
 */
export interface CashFlow {
  id: string
  type: CashFlowType
  /** 发生日期 */
  date: TradingDate
  /** 发生时刻 */
  occurredAt: Timestamp
  /** 金额。正数为流入，负数为流出 */
  amount: Money
  /** 关联订单，外部注资等场景为 null */
  relatedOrderId: Nullable<OrderId>
  remark: Nullable<string>
}
